def is_palindrome(string: str) -> bool:
    """ Test if given string is a palindrome """
    return string == string[::-1]

def manacher(string: str) -> str:
    """ Find the longest palindromic substring of a string """
    T = '#'.join('^{}$'.format(string))
    n = len(T)
    P = [0] * n
    C = R = 0
    for i in range(1, n-1):
        if R > i:
            i_mirror = 2*C - i
            P[i] = min(R - i, P[i_mirror])
        while T[i + 1 + P[i]] == T[i - 1 - P[i]]:
            P[i] += 1
        if i + P[i] > R:
            C, R = i, i + P[i]
    maxLen, centerIndex = max((n, i) for i, n in enumerate(P))
    return string[(centerIndex - maxLen)//2: (centerIndex + maxLen)//2]

def longest_palindromic_suffix(string: str) -> str:
    """ Find the longest palindromic suffix of a string """
    if is_palindrome(string):
        return string
    for i in range(len(string), 0, -1):
        if is_palindrome(string[-i:]):
            return string[-i:]

