def prime_fib(n: int):
    """
    Returns the n-th number that is a Fibonacci number and it's also prime.

    The Fibonacci sequence is a series of numbers where a number is the sum of the two preceding ones, usually starting with 0 and 1.

    Args:
        n (int): The position of the number in the Fibonacci sequence.

    Returns:
        int: The n-th Fibonacci number that is also prime.

    Raises:
        ValueError: If n is less than 1.
        TypeError: If n is not an integer.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")
    if n < 1:
        raise ValueError("Input must be a positive integer.")

    def is_prime(num: int) -> bool:
        """Check if a number is prime."""
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    def miller_rabin(num: int) -> bool:
        """Check if a number is prime using the Miller-Rabin test."""
        if num < 2:
            return False
        if num == 2 or num == 3:
            return True
        if num % 2 == 0:
            return False

        r, s = 0, num - 1
        while s % 2 == 0:
            r += 1
            s //= 2

        for _ in range(5):  # Number of tests to run
            a = random.randrange(2, num - 1)
            x = pow(a, s, num)
            if x == 1 or x == num - 1:
                continue
            for _ in range(r - 1):
                x = pow(x, 2, num)
                if x == num - 1:
                    break
            else:
                return False

        return True

    a, b = 0, 1
    count = 0
    while True:
        if miller_rabin(b):
            count += 1
            if count == n:
                return b
        a, b = b, a + b

